
'use strict';
const $=s=>document.querySelector(s);
const icons={key:'<circle cx="8" cy="15" r="5"/><path d="m12 11 9-9m-4 4 3 3m-6 0 3 3"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><circle cx="11" cy="11" r="4"/><path d="m14 14 4 4"/>',folder:'<path d="M3 7V4h6l3 3h9v13H3z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',more:"<circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"19\" cy=\"12\" r=\"1\"/>",moon:"<path d=\"M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5\"/>",sun:"<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4\"/>"};
const icon=n=>`<svg class="od-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.key}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Every action button carries the shared `btn` base class; `cls` adds variants (primary/quiet/danger/icon/filter).
const btn=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const baseEntries=[['UPDATE_ED25519_PRIVATE_KEY_B64','Release workflow · manifest signing','active'],['UPDATE_ED25519_PUBLIC_KEY_SPKI_B64','Racket updater · SPKI public anchor','active'],['UPDATE_ED25519_PUBLIC_KEY_RAW_TAIL32_B64','Native updater · raw 32-byte public anchor','active'],['RIVET_UPDATE_KEY_ID','Signed update manifest · signing key identifier','active'],['UPDATE_ED25519_NEXT_PRIVATE_KEY_B64','Next release-signing key · not active yet','staged'],['LICENSE_ED25519_PRIVATE_KEY_B64','License signing · separate key lifecycle','other'],['UPDATE_RSA_PUBLIC_KEY_PEM','No known consumer · review before deleting','empty']].map(([name,purpose,group])=>({name,purpose,group}));
const clone=o=>JSON.parse(JSON.stringify(o));
let products=[{name:'rivet',id:'rivet-2026-03a',fp:'9f2c7ea1b4d0e5f3',entries:clone(baseEntries),staged:true,paired:true},{name:'glaze',id:'glaze-2026-03a',fp:'b418d02ce96a7710',entries:clone(baseEntries.filter(e=>!['staged','empty'].includes(e.group))),staged:false,paired:true},{name:'permit',id:'permit-2026-03a',fp:'c7d104a29be3f885',entries:[{name:'LICENSE_ED25519_PRIVATE_KEY_B64',purpose:'License signing · value is empty',group:'empty'},{name:'LICENSE_ED25519_PUBLIC_KEY_B64',purpose:'License verification · value is empty',group:'empty'}],staged:false,paired:false},{name:'commerce',id:'',fp:'',entries:[],staged:false,paired:false}];
let selected=0,filter='all',vault=document.body.dataset.screen!=='onboarding',timer=null,remaining=0,trigger=null,pending=null,scanResults=false,theme=null;
// theme: null follows the system. The toggle is a review control for the prototype only; the product has no theme setting.
const isDark=()=>theme?theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches;
function setTheme(next){theme=next;document.documentElement.dataset.theme=next||'';render();}
// Sidebar footer actions. Labels collapse to icons in narrow windows; aria-label keeps the accessible name.
function sideActions(){const items=[['Snapshots','snapshots','history',!vault?'disabled':''],['Scan for stray keys','scan','scan',!vault?'disabled':''],['Choose vault\u2026','vault','folder','']];return items.map(([label,action,glyph,dis])=>btn(icon(glyph)+`<span class="lbl">${label}</span>`,action,'quiet',`aria-label="${label}"${dis?' '+dis:''}`)).join('');}
function themeToggle(){const dark=isDark();return btn(icon(dark?'sun':'moon'),'theme','quiet icon',`aria-label="${dark?'Switch to light theme':'Switch to dark theme'}" title="${dark?'Switch to light theme':'Switch to dark theme'}"`);}
let snapshots=[{label:'2026-11-10 23:41:07',why:'Before staging the next rivet key',data:clone(products).map((p,i)=>i? p:{...p,staged:false,entries:p.entries.filter(e=>e.group!=='staged')})},{label:'2026-11-10 21:07:33',why:'Before importing the license-signing entry',data:clone(products)}];
const product=()=>products[selected];
const hasWarning=p=>p.entries.some(e=>e.group==='empty');
const stateLabel=p=>!p.entries.length?'No entries':hasWarning(p)?`${p.entries.filter(e=>e.group==='empty').length} empty entries`:p.paired?'Pair verified':'Not checked';
function saveSnapshot(why){snapshots.unshift({label:new Date().toLocaleString('en-GB',{hour12:false}),why,data:clone(products)});}
function message(text){$('#feedback').textContent=text;}
function render(){
const p=product(),paired=products.filter(p=>p.paired).length,warnings=products.filter(hasWarning).length;
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('key')}</span><div><strong>Keyward</strong><small>Release-signing key vault</small></div></div><div class="summary"><div class="od-stat"><strong>${vault?products.length:0}</strong><small>Products</small></div><div class="od-stat"><strong>${vault?paired:0}</strong><small>Paired</small></div><div class="od-stat"><strong>${vault?warnings:0}</strong><small>Attention</small></div></div><nav aria-label="Products"><div class="navlabel">Products</div>${vault?products.map((p,i)=>`<button type="button" class="product" aria-current="${selected===i}" data-product="${i}"><span class="dot ${!p.entries.length?'neutral':hasWarning(p)?'warn':''}"></span><span class="od-field"><span class="name">${esc(p.name)}</span><small>${stateLabel(p)}</small></span><span class="count">${p.entries.length}</span></button>`).join(''):'<p class="small muted">No vault selected</p>'}</nav><div class="sidebottom">${sideActions()}<p class="trust">Values stay off screen.<br>Vaults and snapshots are plain text on disk.</p></div><select class="mobilepicker" id="productPicker" aria-label="Select product" ${!vault?'disabled':''}>${products.map((p,i)=>`<option value="${i}" ${selected===i?'selected':''}>${esc(p.name)}</option>`).join('')}</select></aside><main class="main"><div class="topline"><span class="breadcrumb">Vault / ${vault?'Products':'Get started'}</span><span class="toplineend"><span class="demo">Interactive prototype · sample data</span>${themeToggle()}</span></div>${vault?mainView(p):emptyView()}</main><footer class="footer"><p id="feedback" role="status" aria-live="polite">${remaining?`Copy simulation · ${remaining}s remaining. No clipboard access.`:'Prototype only · no vault file is read or changed.'}</p><span class="mono">${vault?'~/Sync/Keys/secrets.ini':'No vault selected'}</span></footer></div>`;
}
function emptyView(){return `<div class="empty">${icon('key')}<h1>Your keys, kept out of view.</h1><p>Choose a signing-key vault to review its products, verify key pairs and manage a safe rotation.</p>${btn('Choose Vault…','vault','primary')}<p class="small">The vault and its history remain plain text.<br>Use a trusted folder and separate encrypted backups.</p><p class="small">This prototype opens sample data only.</p></div>`;}
function mainView(p){const entries=p.entries.filter(e=>filter==='all'||filter==='attention'&&e.group==='empty'||filter==='staged'&&e.group==='staged');return `<header class="heading"><div><div class="eyebrow">Release-signing keys</div><h1>${esc(p.name)}</h1><p><span class="status ${hasWarning(p)?'warn':''}">${icon(hasWarning(p)?'lock':'check')}${stateLabel(p)}</span></p></div><div class="actions">${btn(icon('history')+' Snapshots','snapshots')}${btn(icon('check')+' Deep Check','check')}</div></header><dl class="metadata"><div><dt>Active key ID</dt><dd class="mono">${esc(p.id||'Not configured')}</dd></div><div><dt>Fingerprint · SHA-256 prefix</dt><dd class="mono">${esc(p.fp||'Not available')}</dd></div><div><dt>Pairing</dt><dd class="small">${p.paired?'Public and private keys match':'Run Deep Check to review'}</dd></div></dl>${rotationView(p)}<section aria-labelledby="entriesTitle"><div class="sectionhead entrieshead"><div><h2 id="entriesTitle">Entries <span class="count">${p.entries.length}</span></h2><p>Names and purposes only. Values are never displayed.</p></div>${btn('Add entry…','add')}</div><div class="filters" role="group" aria-label="Filter entries">${[['all','All entries'],['staged','Staged'],['attention','Needs attention']].map(([id,label])=>btn(label,'filter','filter',`data-filter="${id}" aria-pressed="${filter===id}"`)).join('')}</div>${entries.length?entries.map(e=>`<article class="entry">${icon('lock')}<div class="entrymain">${btn(esc(e.name),'entry','entryname',`data-name="${esc(e.name)}"`)}<p>${esc(e.purpose)}</p></div>${e.group==='empty'?'<span class="tag warn">Empty value</span>':e.group==='staged'?'<span class="tag">Staged</span>':''}<div class="entryactions">${e.group!=='empty'?btn(icon('copy')+' Copy','copy','quiet',`data-name="${esc(e.name)}"`):btn('Import…','import','quiet',`data-name="${esc(e.name)}"`)}${btn(icon('more'),'entry','icon',`aria-label="Actions for ${esc(e.name)}" data-name="${esc(e.name)}"`)}</div></article>`).join(''):`<div class="empty"><h3>${p.entries.length?'No matching entries':'No entries yet'}</h3><p>${p.entries.length?'Choose All entries to return to the complete list.':'Add an entry to start organizing this product’s signing keys.'}</p>${btn(p.entries.length?'Show all entries':'Add entry…',p.entries.length?'resetfilter':'add')}</div>`}</section>`;}
function rotationView(p){return `<section class="rotation" aria-labelledby="rotationTitle"><div class="sectionhead"><div><div class="eyebrow">Two-stage key rotation</div><h2 id="rotationTitle">${p.staged?'Ship trust before switching keys.':'Prepare the next signing key.'}</h2></div><span class="tag">${p.staged?'Stage 1 · staged':'No rotation in progress'}</span></div>${p.staged?`<p class="small muted">Next key <span class="mono">${esc(p.name)}-2026-11b</span> · <span class="mono">5ae3c9d14b80f261</span></p><ol class="steps"><li class="step done"><span class="stepnum">01 / READY</span><h3>Stage & verify</h3><p>The next key pair has passed pairing.</p></li><li class="step current"><span class="stepnum">02 / NEXT</span><h3>Ship public anchors</h3><p>Add the next public anchors. Ship a release signed with the current key.</p></li><li class="step"><span class="stepnum">03 / THEN</span><h3>Switch & promote</h3><p>After that release ships, switch the CI secret to the staged key. Then promote.</p></li></ol><div class="rotationfoot"><p>Promote replaces the active key and removes staged entries. A snapshot is saved first.</p><div class="actions">${btn('Discard…','discard','quiet danger')}${btn('Review promotion '+icon('arrow'),'promote')}</div></div>`:`<p class="muted">Stage a new key pair while keeping the current signing key active. Review the changes before continuing.</p><div class="rotationfoot"><p>Existing releases keep trusting the current key until the new public anchors ship.</p>${btn('Stage next key…','stage')}</div>`}</section>`;}
function openDialog(title,description,body,foot=''){trigger=document.activeElement;const d=$('#modal');d.innerHTML=`<div class="modalhead"><div><h2 id="modalTitle">${title}</h2><p>${description}</p></div>${btn(icon('close'),'close','icon','aria-label="Close dialog"')}</div><div class="modalbody">${body}</div><div class="modalfoot">${foot||btn('Done','close','primary')}</div>`;if(!d.open)d.showModal();const focus=d.querySelector('[data-action="cancel"]')||d.querySelector('input:not([type=checkbox])')||d.querySelector('[data-action="close"]');focus?.focus();}
function closeDialog(){const previous=trigger;$('#modal').close();pending=null;if(previous?.isConnected)previous.focus();else{const name=previous?.dataset.name;const same=name?[...document.querySelectorAll('button[data-name]')].find(b=>b.dataset.name===name):null;(same||document.querySelector('[data-action="check"]')||document.querySelector('[data-action="vault"]'))?.focus();}}
function confirmation(kind,title,description,body,label){pending=kind;openDialog(title,description,body,btn(label,'confirm','danger')+btn('Cancel','cancel','primary','autofocus'));}
function showSnapshots(){openDialog('Store snapshots','Every change saves a copy before modifying the vault.',`<div class="notice">Snapshots are plain text beside the vault. They are recovery copies, not encrypted backups. Restoring affects the whole vault.</div>${snapshots.map((s,i)=>`<div class="snapshot"><div class="od-field"><strong class="mono">${esc(s.label)}</strong><small>${esc(s.why)}</small></div>${btn('Restore…','restore','',`data-index="${i}"`)}</div>`).join('')}`);}
function showScan(){openDialog('Scan for stray keys','Find signing-key material outside the vault without displaying its value.',`<div class="notice">Sample results only. No folders are accessed. The vault and its .history folder are excluded from the scan.</div><div class="field"><label for="scanPath">Folder to scan</label><input id="scanPath" value="~/Codes/release-workspace" readonly></div>${scanResults?`<p class="status warn">3 sample findings · review these files</p>${[['scripts/release.sh','line 42 · ed25519-private','9f2c7ea1b4d0e5f3'],['build/key.der','line 1 · base64-der','c7d104a29be3f885'],['notes/rotation-checklist.md','line 12 · minisign-secret','b418d02ce96a7710']].map(([path,meta,fp])=>`<div class="scanitem"><strong class="mono">${path}</strong><p>${meta}</p><span class="mono">Fingerprint ${fp}</span></div>`).join('')}`:'<p class="muted">Choose Scan to explore the example findings. Only paths, line numbers and fingerprints are shown.</p>'}`,btn('Close','close')+btn(scanResults?'Scan again':'Scan folder','runscan','primary'));}
function copySimulation(name){clearInterval(timer);remaining=30;message(`Copy simulation: ${name}. A real copy exposes the clipboard to other apps; it clears after 30s. No value was copied.`);timer=setInterval(()=>{remaining--;if(!remaining){clearInterval(timer);message('Copy simulation finished · no value was placed on or cleared from your clipboard.');}else message(`Copy simulation · ${remaining}s until expiry. No clipboard access.`);},1000);}
function showEntry(name){const e=product().entries.find(e=>e.name===name);if(!e)return;openDialog('Entry details','Values are never displayed.',`<div class="field"><span class="small muted">Name</span><strong class="mono fullvalue">${esc(e.name)}</strong></div><div class="field"><span class="small muted">Purpose</span><p>${esc(e.purpose)}</p></div><span class="tag ${e.group==='empty'?'warn':''}">${e.group==='empty'?'Empty value':e.group==='staged'?'Staged key':'Stored entry'}</span>`,btn('Delete…','delete','danger',`data-name="${esc(e.name)}"`)+btn(e.group==='empty'?'Import…':'Copy',e.group==='empty'?'import':'copy','',`data-name="${esc(e.name)}"`)+btn('Done','close','primary'));}
async function act(action,b){const p=product();switch(action){
case 'theme':setTheme(isDark()?'light':'dark');document.querySelector('[data-action="theme"]')?.focus();break;
case 'close':case 'cancel':closeDialog();break;
case 'vault':openDialog('Choose a vault','Prototype demonstration',`<p>The real app uses the system file picker. Here, open the sample vault without reading or changing any local file.</p><p class="small muted">Do not paste real keys into this prototype. Sample edits last only while this page remains open.</p>`,btn('Cancel','cancel')+btn('Open sample vault','openvault','primary'));break;
case 'openvault':vault=true;filter='all';render();closeDialog();message('Sample vault opened · no local files accessed.');break;
case 'filter':filter=b.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`)?.focus();break;
case 'resetfilter':filter='all';render();document.querySelector('[data-filter="all"]')?.focus();break;
case 'snapshots':showSnapshots();break;
case 'scan':showScan();break;
case 'runscan':scanResults=true;showScan();break;
case 'copy':copySimulation(b.dataset.name);if($('#modal').open)closeDialog();break;
case 'entry':showEntry(b.dataset.name);break;
case 'check':b.disabled=true;b.textContent='Checking sample data…';message('Reviewing sample entry metadata…');await new Promise(r=>setTimeout(r,450));p.paired=Boolean(p.entries.length&&!hasWarning(p));render();message(`Sample check complete · ${stateLabel(p)}. No cryptographic verification was performed.`);document.querySelector('[data-action="check"]')?.focus();break;
case 'promote':if(!p.staged)return;confirmation('promote','Promote the staged signing key?','Review the release handoff before changing the active key.',`<p>The active signing entries will take the staged values. NEXT entries will be removed. A whole-vault snapshot is saved first.</p><p class="small muted">Key pairing is ${p.paired?'verified in the sample state':'not verified'}. Keyward cannot verify your external release or CI configuration.</p><label class="checkrow"><input id="releaseReady" type="checkbox"><span>The phase-1 release shipped with the new public anchors, signed by the old key.</span></label><label class="checkrow"><input id="ciReady" type="checkbox"><span>After that release shipped, I switched the CI signing secret to the staged private key.</span></label><p class="error" id="confirmError" hidden>Confirm both handoff steps before promoting.</p>`,'Promote');$('#modal [data-action="confirm"]').disabled=!p.paired||!p.staged;break;
case 'discard':confirmation('discard','Discard the staged key?','The active signing key stays unchanged.',`<p>The staged key and NEXT entries will be removed. A snapshot is saved first and can restore the vault.</p>`,'Discard staged key');break;
case 'stage':confirmation('stage','Stage the next signing key?','Keep the current signing key active.',`<p>A new pair is staged for the two-stage release handoff. A snapshot is saved first.</p><div class="notice">This prototype adds sample metadata only. It does not generate key material.</div>`,'Stage sample key');break;
case 'delete':confirmation({type:'delete',name:b.dataset.name},'Delete this entry?','Check its consumer before removing it.',`<p class="mono">${esc(b.dataset.name)}</p><p>${esc(p.entries.find(e=>e.name===b.dataset.name)?.purpose||'')}</p><p>A consuming release workflow may fail after deletion. A snapshot is saved first; restoring it replaces the whole vault.</p>`,'Delete entry');break;
case 'restore':confirmation({type:'restore',index:Number(b.dataset.index)},'Restore this vault snapshot?','This replaces every product’s current entries.',`<p>Restore the sample vault to <strong>${esc(snapshots[Number(b.dataset.index)].label)}</strong>?</p><p>A snapshot of the current vault will be saved first. Changes after the selected snapshot will be replaced.</p>`,'Restore vault');break;
case 'confirm':{
if(pending==='promote'&&(!$('#releaseReady').checked||!$('#ciReady').checked)){$('#confirmError').hidden=false;$('#releaseReady').focus();return;}
const operation=pending;const restored=operation?.type==='restore'?clone(snapshots[operation.index].data):null;
saveSnapshot(typeof operation==='string'?`Before ${operation} · ${p.name}`:`Before ${operation.type} · ${p.name}`);
if(operation==='promote'){p.id=p.name+'-2026-11b';p.fp='5ae3c9d14b80f261';p.staged=false;p.entries=p.entries.filter(e=>e.group!=='staged');}
if(operation==='discard'){p.staged=false;p.entries=p.entries.filter(e=>e.group!=='staged');}
if(operation==='stage'){p.staged=true;p.paired=!hasWarning(p);p.entries.push({name:'UPDATE_ED25519_NEXT_PRIVATE_KEY_B64',purpose:'Staged release-signing key · sample metadata',group:'staged'});}
if(operation?.type==='delete'){p.entries=p.entries.filter(e=>e.name!==operation.name);p.paired=false;if(operation.name.includes('_NEXT_'))p.staged=false;}
if(restored)products=restored;
filter='all';render();closeDialog();message('Sample change applied · a recovery snapshot was saved. No vault file was changed.');break;}
case 'add':case 'import':{
const importing=action==='import';openDialog(importing?'Import entry metadata':'Add entry metadata','Prototype only · never enter real signing-key material.',`<div class="field"><label for="entryName">Entry name</label><input id="entryName" autocomplete="off" value="${importing?esc(b.dataset.name):''}" ${importing?'readonly':''}><p class="error" id="nameError" hidden>Use a unique entry name containing letters, digits and underscores.</p></div><div class="field"><label for="entryPurpose">Purpose</label><input id="entryPurpose" autocomplete="off" placeholder="For example, release manifest signing"><p class="error" id="purposeError" hidden>Describe what consumes this entry.</p></div><div class="notice">Only names and purposes are stored in page memory. Importing real key material requires the native app.</div>`,btn('Cancel','cancel')+btn(importing?'Apply sample import':'Add sample entry','saveentry','primary',`data-import="${importing}"`));break;}
case 'saveentry':{
const name=$('#entryName').value.trim(),purpose=$('#entryPurpose').value.trim(),importing=b.dataset.import==='true';const invalid=!/^[A-Z][A-Z0-9_]{2,100}$/.test(name)||(!importing&&p.entries.some(e=>e.name===name));$('#nameError').hidden=!invalid;$('#purposeError').hidden=Boolean(purpose);if(invalid||!purpose){(invalid?$('#entryName'):$('#entryPurpose')).focus();return;}saveSnapshot(`Before sample ${importing?'import':'add'} · ${p.name}`);if(importing){const e=p.entries.find(e=>e.name===name);if(e){e.group='other';e.purpose=purpose;}}else p.entries.push({name,purpose,group:'empty'});p.paired=false;filter='all';render();closeDialog();message(importing?'Sample import applied · metadata only, no real key imported.':'Entry metadata added · value remains empty. No vault file changed.');break;}
}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.product!==undefined){selected=Number(b.dataset.product);filter='all';render();document.querySelector(`[data-product="${selected}"]`)?.focus();return;}if(b.dataset.action)act(b.dataset.action,b);});
document.addEventListener('change',e=>{if(e.target.id==='productPicker'){selected=Number(e.target.value);filter='all';render();$('#productPicker').focus();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&$('#modal').open){if(e.target.tagName==='INPUT'&&e.target.type!=='checkbox'&&$('#modal [data-action="saveentry"]')){e.preventDefault();act('saveentry',$('#modal [data-action="saveentry"]'));}else if(pending){e.preventDefault();closeDialog();}}if((e.metaKey||e.ctrlKey)&&['o','r','l'].includes(e.key.toLowerCase())){e.preventDefault();if($('#modal').open)closeDialog();const action={o:'vault',r:'check',l:'snapshots'}[e.key.toLowerCase()];if(!vault&&action!=='vault')return;act(action,document.querySelector(`[data-action="${action}"]`)||document.createElement('button'));}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
render();
const initial=document.body.dataset.screen;if(initial==='rotation')act('promote');if(initial==='snapshots')showSnapshots();if(initial==='stray-scan'){scanResults=true;showScan();}
